(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-331":{scenario:{company:"Mộc Lan Home Appliances",supervisor:{name:"Bùi Ngọc Ánh",role:{vi:"Trưởng nhóm Vận hành Sàn TMĐT",en:"Marketplace Operations Lead"}},ref_code:"FS-1212",title:{vi:"Đúng giá gốc. Đúng lãi. Đúng luật chơi.",en:"Right reference price. Right margin. Fair play."},brief:{vi:"Bạn thiết lập flash sale 12.12 trên sàn thương mại điện tử cho nồi chiên không dầu mã NC-55L, giá bán 1290000 đồng. Lịch sử giá 30 ngày: giá bán thực tế 1590000 đồng; tuần trước có người nâng giá niêm yết lên 1890000; giá in trên hộp 2100000 chưa từng áp dụng. Shop tài trợ voucher 50000 đồng/đơn; giá vốn 820000, đóng gói 15000; tổng phí sàn mô phỏng 15%. Sửa giá gốc hiển thị và lãi đóng góp mỗi đơn, rồi lập báo cáo có căn cứ.",en:"You are setting up the 12.12 flash sale on a marketplace for air fryer NC-55L at 1290000 VND. 30-day price history: actual selling price 1590000 VND; last week someone raised the list price to 1890000; the 2100000 printed on the box was never used. The shop funds a 50000 VND voucher per order; cost of goods 820000, packaging 15000; total training marketplace fees 15%. Correct the displayed reference price and the contribution margin per order, then write an evidence-based report."},reference_title:{vi:"Lịch sử giá 30 ngày & bảng tính lãi chiến dịch đã duyệt · FS-1212",en:"Approved 30-day price history & campaign margin sheet · FS-1212"},fields:[{id:"ORIG_PRICE",label:{vi:"Giá gốc hiển thị (VND)",en:"Displayed reference price (VND)"},initial:"1890000",expected:"1590000",choices:["1890000","1590000","2100000"],reference:"Lịch sử giá 30 ngày",hint:{vi:"Giá gốc phải là giá đã thực sự bán cho khách trước chương trình, không phải giá vừa nâng hay giá in sẵn.",en:"The reference price must be the price actually charged before the campaign, not a raised or printed price."}},{id:"CM_PER_ORDER",label:{vi:"Lãi đóng góp mỗi đơn (VND)",en:"Contribution margin per order (VND)"},initial:"351800",expected:"219000",reference:"Bảng tính lãi chiến dịch",ref_value:{vi:"Giá flash sale 1290000; voucher shop 50000; phí sàn 8% + 4% + 3%; giá vốn 820000; đóng gói 15000",en:"Flash price 1290000; shop voucher 50000; fees 8% + 4% + 3%; cost 820000; packaging 15000"},hint:{vi:"Bản nháp chỉ trừ hoa hồng trên giá chưa trừ voucher và quên phí thanh toán, phí chiến dịch.",en:"The draft deducts only commission on the pre-voucher price and forgets payment and campaign fees."}}],sop32:{vi:"Lãi đóng góp mỗi đơn = (giá flash sale - voucher shop tài trợ) x (1 - tổng phí sàn 15% gồm hoa hồng 8%, thanh toán 4%, chiến dịch 3%) - giá vốn - đóng gói. Phí tính trên giá sau voucher shop (mô phỏng).",en:"Contribution per order = (flash price - shop-funded voucher) x (1 - total fees 15%: commission 8%, payment 4%, campaign 3%) - cost of goods - packaging. Fees apply to the post-voucher price (training)."},context:{label:"SELLER CENTER / FS-1212",metrics:[{label:{vi:"Giá flash sale",en:"Flash sale price"},value:"1,290,000 VND"},{label:{vi:"Voucher shop tài trợ",en:"Shop-funded voucher"},value:"50,000 VND"},{label:{vi:"Tổng phí sàn mô phỏng",en:"Training fee total"},value:"15%"},{label:{vi:"Giá vốn",en:"Cost of goods"},value:"820,000 VND"}]},crisis:{vi:"Trưởng phòng kinh doanh online nhắn: “Tạo 300 đơn ảo bằng tài khoản người quen rồi đánh giá 5 sao để NC-55L lên top trước giờ flash sale, chi phí công ty chịu.”",en:"The online sales manager messages you: “Create 300 fake orders from friends' accounts and leave 5-star reviews so NC-55L ranks top before the flash sale, the company pays.”"},options:{safe:{vi:"Từ chối tạo đơn ảo, đánh giá giả và báo Trưởng nhóm Vận hành; đề xuất quảng cáo trong sàn, tối ưu nội dung sản phẩm và mời người mua thật đánh giá sau khi nhận hàng.",en:"Refuse fake orders and reviews and inform the Operations Lead; propose in-platform ads, better listing content and inviting real buyers to review after delivery."},shortcut:{vi:"Tạo một ít đơn ảo bằng tài khoản người quen cho an toàn rồi xóa đánh giá sau chiến dịch.",en:"Create a few fake orders from friends' accounts to be safe and delete the reviews after the campaign."},wait:{vi:"Không làm gì, chờ xem các shop khác có làm không rồi tính sau.",en:"Do nothing and wait to see whether other shops do it."}},questions:{vi:["Vì sao giá gốc hiển thị phải là 1590000 chứ không phải 1890000 hay 2100000? Dữ liệu nào chứng minh?","Trình bày cách tính lãi đóng góp mỗi đơn và hậu quả với shop nếu tạo đơn ảo, đánh giá giả."],en:["Why must the reference price be 1590000 rather than 1890000 or 2100000? Which data proves it?","Explain the contribution margin calculation and the consequences for the shop of fake orders and reviews."]},hints:{vi:["Đặt bản nháp cạnh lịch sử giá 30 ngày, đánh dấu mức giá khách đã thực sự trả.","Tính theo SOP mục 3.2: trừ voucher shop trước, áp đủ ba loại phí rồi trừ giá vốn và đóng gói.","Đọc lại SOP mục 4.2: thao túng đơn hàng, đánh giá là vi phạm; mọi yêu cầu như vậy phải báo cáo."],en:["Place the draft next to the 30-day price history and mark the price buyers actually paid.","Compute per SOP 3.2: deduct the shop voucher first, apply all three fees, then cost and packaging.","Re-read SOP 4.2: manipulating orders or reviews is a violation and any such request must be escalated."]}},learning:{summary:{vi:"Chuyên viên vận hành gian hàng thương mại điện tử quản lý hoạt động hằng ngày của shop trên các sàn: đăng và tối ưu sản phẩm, quản lý giá, tồn kho, chương trình khuyến mại, xử lý đơn hàng, vận chuyển, đổi trả, đánh giá và chỉ số sức khỏe gian hàng. Nghề đòi hỏi đọc dữ liệu nhanh, tính đúng lãi sau phí sàn, nắm chính sách từng sàn và tuân thủ pháp luật về thương mại điện tử, khuyến mại và bảo vệ người tiêu dùng.",en:"An e-commerce store operations specialist runs a shop's daily activity on marketplaces: listing and optimizing products, managing prices, stock and promotions, processing orders, shipping, returns, reviews and store health metrics. The role needs fast data reading, correct margin math after platform fees, knowledge of each platform's policy and compliance with e-commerce, promotion and consumer protection law."},responsibilities:{vi:["Đăng sản phẩm đúng ngành hàng, tối ưu tiêu đề, hình ảnh, thuộc tính và từ khóa.","Thiết lập giá, voucher, flash sale và tính lãi sau phí sàn trước khi chạy chiến dịch.","Đồng bộ tồn kho đa sàn, theo dõi đơn hàng, đóng gói và bàn giao vận chuyển đúng hạn.","Xử lý đổi trả, khiếu nại, đánh giá và giữ chỉ số vận hành shop trong ngưỡng an toàn.","Báo cáo doanh số, tỷ lệ chuyển đổi, chi phí quảng cáo và đề xuất tối ưu hằng tuần."],en:["List products in the right category and optimize titles, images, attributes and keywords.","Set prices, vouchers and flash sales and compute post-fee margin before each campaign.","Sync stock across platforms, track orders, pack and hand over to carriers on time.","Handle returns, complaints and reviews and keep store metrics within safe limits.","Report sales, conversion and ad spend weekly with optimization proposals."]},competencies:[{name:{vi:"Tối ưu hiển thị sản phẩm",en:"Listing optimization"},desc:{vi:"Viết tiêu đề, mô tả, chọn từ khóa và hình ảnh giúp sản phẩm được tìm thấy và chuyển đổi tốt.",en:"Write titles and descriptions and choose keywords and images that get found and convert."}},{name:{vi:"Định giá & khuyến mại",en:"Pricing & promotions"},desc:{vi:"Thiết kế khuyến mại có lãi, đúng quy định về giá gốc và mức giảm.",en:"Design profitable promotions that respect reference price and discount rules."}},{name:{vi:"Vận hành đơn hàng",en:"Order operations"},desc:{vi:"Kiểm soát tồn kho, thời gian chuẩn bị hàng, tỷ lệ hủy và giao trễ.",en:"Control stock, preparation time, cancellation and late shipment rates."}},{name:{vi:"Phân tích dữ liệu shop",en:"Store analytics"},desc:{vi:"Đọc lưu lượng, tỷ lệ chuyển đổi, ROAS để quyết định nhanh dựa trên số liệu.",en:"Read traffic, conversion and ROAS to make fast data-based decisions."}},{name:{vi:"Tuân thủ & trung thực",en:"Compliance & honesty"},desc:{vi:"Không giảm giá ảo, không đơn ảo, không đánh giá giả, thông tin sản phẩm trung thực.",en:"No fake discounts, fake orders or fake reviews, and truthful product information."}}],knowledge:{vi:["Nghị định 52/2013/NĐ-CP về thương mại điện tử (sửa đổi bởi Nghị định 85/2021/NĐ-CP) và các quy định mới về thương mại điện tử.","Luật Bảo vệ quyền lợi người tiêu dùng 2023: thông tin trung thực về hàng hóa, giá, khuyến mại và quyền đổi trả.","Nghị định 81/2018/NĐ-CP về xúc tiến thương mại: hình thức khuyến mại, mức giảm giá tối đa và nghĩa vụ thông báo.","Cơ cấu phí sàn: hoa hồng, phí thanh toán, phí dịch vụ chiến dịch, phí vận chuyển và cách tính lãi sau phí.","Chỉ số sức khỏe gian hàng: tỷ lệ hủy, giao trễ, phản hồi chat, điểm phạt và hậu quả."],en:["Decree 52/2013/ND-CP on e-commerce (amended by Decree 85/2021/ND-CP) and newer e-commerce rules.","Consumer Protection Law 2023: truthful product, price and promotion information and return rights.","Decree 81/2018/ND-CP on trade promotion: promotion types, maximum discount and notification duties.","Marketplace fee structure: commission, payment fee, campaign fee, shipping and post-fee margin.","Store health metrics: cancellation, late shipment, chat response, penalty points and their effects."]},tools:["Kênh người bán (seller center) của sàn","Phần mềm quản lý bán hàng đa kênh (OMS)","Công cụ quảng cáo trong sàn","Bảng tính giá & lãi chiến dịch","Hệ thống chat tập trung"],kpis:{vi:["Tổng giá trị hàng hóa bán ra (GMV) và tỷ lệ chuyển đổi.","Tỷ lệ giao hàng đúng hạn và tỷ lệ đơn hủy do shop.","Doanh thu trên chi phí quảng cáo (ROAS).","Điểm đánh giá trung bình và tỷ lệ phản hồi chat."],en:["Gross merchandise value (GMV) and conversion rate.","On-time shipment rate and seller-caused cancellation rate.","Return on ad spend (ROAS).","Average rating and chat response rate."]},day:[{time:"08:00",vi:"Kiểm tra đơn hàng qua đêm, tồn kho đa sàn và cảnh báo vận hành.",en:"Check overnight orders, multi-platform stock and store warnings."},{time:"09:30",vi:"Xử lý đơn, in vận đơn và bàn giao cho đơn vị vận chuyển trước giờ lấy hàng.",en:"Process orders, print waybills and hand over before carrier pickup."},{time:"11:00",vi:"Tối ưu tiêu đề, hình ảnh cho sản phẩm có tỷ lệ chuyển đổi thấp.",en:"Optimize titles and images for low-converting products."},{time:"14:00",vi:"Cài flash sale, voucher và kiểm tra lãi sau phí trên bảng tính.",en:"Set up flash sales and vouchers and check post-fee margin in the sheet."},{time:"16:30",vi:"Phản hồi đánh giá, khiếu nại và gửi báo cáo ngày cho trưởng nhóm.",en:"Answer reviews and complaints and send the daily report to the lead."}],mistakes:{vi:["Nâng giá niêm yết ngay trước chương trình để hiển thị mức giảm giá ảo.","Tính lãi quên phí thanh toán, phí chiến dịch hoặc voucher do shop tài trợ.","Tạo đơn ảo, mua đánh giá giả để lên top, dẫn tới phạt điểm hoặc khóa shop."],en:["Raising the list price just before a campaign to show a fake discount.","Computing margin without payment fees, campaign fees or shop-funded vouchers.","Creating fake orders or buying reviews to rank higher, leading to penalties or store bans."]},career:[{vi:"Nhân viên xử lý đơn hàng thương mại điện tử",en:"E-commerce order processing assistant"},{vi:"Chuyên viên vận hành gian hàng",en:"Store operations specialist"},{vi:"Trưởng nhóm vận hành sàn thương mại điện tử",en:"Marketplace operations team lead"},{vi:"Quản lý kênh thương mại điện tử",en:"E-commerce channel manager"}],glossary:[{term:"GMV",vi:"Tổng giá trị hàng hóa bán ra trong kỳ, chưa trừ hủy, trả hàng và phí.",en:"Gross merchandise value sold in a period, before cancellations, returns and fees."},{term:"ROAS",vi:"Doanh thu tạo ra trên mỗi đồng chi phí quảng cáo.",en:"Revenue generated per unit of ad spend."},{term:"Flash sale",vi:"Chương trình giảm giá trong khung giờ ngắn với số lượng giới hạn.",en:"A short time-boxed discount with limited quantity."},{term:"SKU",vi:"Mã định danh từng phiên bản sản phẩm theo màu, dung tích, kích cỡ.",en:"A unique code for each product variant by color, capacity or size."},{term:"Brushing",vi:"Đơn ảo: tạo giao dịch giả để thổi phồng doanh số, xếp hạng và đánh giá.",en:"Fake transactions created to inflate sales, ranking and reviews."}],quiz:[{q:{vi:"Giá bán 500000 đồng, voucher shop 20000, phí sàn 10% tính trên giá sau voucher, giá vốn 300000. Lãi đóng góp mỗi đơn là bao nhiêu?",en:"Price 500000 VND, shop voucher 20000, 10% fees on the post-voucher price, cost 300000. What is the contribution per order?"},options:{vi:["132000 đồng","150000 đồng","180000 đồng","128000 đồng"],en:["132000 VND","150000 VND","180000 VND","128000 VND"]},answer:0,explain:{vi:"(500000 - 20000) x 90% - 300000 = 432000 - 300000 = 132000 đồng.",en:"(500000 - 20000) x 90% - 300000 = 432000 - 300000 = 132000 VND."}},{q:{vi:"Giá gốc hiển thị khi chạy giảm giá phải là giá nào?",en:"Which price must be shown as the reference price in a discount?"},options:{vi:["Giá cao nhất từng niêm yết","Giá in trên bao bì","Giá thực tế đã bán ngay trước chương trình","Giá của đối thủ"],en:["The highest list price ever","The price printed on the pack","The actual selling price right before the campaign","A competitor's price"]},answer:2,explain:{vi:"Mức giảm phải tính trên giá bán thật trước khuyến mại; nâng giá rồi giảm là thông tin gây nhầm lẫn cho người tiêu dùng.",en:"Discounts must be based on the real pre-promotion price; raising then cutting misleads consumers."}},{q:{vi:"Cấp trên yêu cầu tạo đơn ảo và đánh giá 5 sao để lên top. Bạn làm gì?",en:"Your manager asks for fake orders and 5-star reviews to rank higher. What do you do?"},options:{vi:["Làm theo vì công ty chịu chi phí","Từ chối, báo cáo và đề xuất cách tăng hiển thị hợp lệ","Chỉ tạo 50 đơn cho an toàn","Thuê đơn vị bên ngoài làm thay"],en:["Comply because the company pays","Refuse, escalate and propose lawful ways to gain visibility","Make only 50 orders to be safe","Hire an outside agency to do it"]},answer:1,explain:{vi:"Đơn ảo, đánh giá giả lừa dối người mua, vi phạm chính sách sàn và có thể khiến shop bị khóa.",en:"Fake orders and reviews deceive buyers, break platform policy and can get the store banned."}},{q:{vi:"Theo Nghị định 81/2018/NĐ-CP, mức giảm giá tối đa thông thường cho hàng hóa khuyến mại là bao nhiêu?",en:"Under Decree 81/2018/ND-CP, what is the usual maximum discount for promoted goods?"},options:{vi:["30%","70%","100%","50% giá ngay trước khuyến mại"],en:["30%","70%","100%","50% of the price right before the promotion"]},answer:3,explain:{vi:"Mức giảm thông thường không vượt quá 50%; một số chương trình khuyến mại tập trung theo quy định được áp dụng mức cao hơn.",en:"The usual cap is 50%; certain officially designated concentrated promotion programs allow more."}}],tools_en:["Marketplace seller center","Multichannel order management software (OMS)","In-marketplace advertising tools","Pricing & campaign margin spreadsheets","Centralized chat system"]}}})})(window.KKR);
